xql_query:
// ============================================================
// Rule: CTX_Suspicious Code Hosting Download Followed by MSI Installation
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Suspicious Code Hosting Download Followed by MSI Installation.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1059 - Command and Scripting Interpreter

// Title: CTX - Suspicious Code Hosting Download Followed by MSI Installation
// Description: Detecta download de MSI/EXE/JS a partir de serviços de hospedagem de código ou arquivos públicos,
// seguido de instalação/execução local. Útil para detectar campanhas de fake software e dropper inicial.
// MITRE ATT&CK: T1059 (Execution), T1105 (Ingress Tool Transfer), T1218.007 (Msiexec - Defense Evasion)
//
// NOTA TH: Atacantes abusam de infraestrutura legítima (GitHub raw, Discord CDN, Cloudflare Workers)
// para bypass de reputação de domínio em proxy/firewall. Vetor mais comum: fake-software + msiexec silencioso.
// Pivô recomendado após disparo: agent_hostname → artefatos em %TEMP% e conexões de rede subsequentes.
//
// ALLOWLIST: Excluir build servers e pipelines CI/CD autorizados.
// Adicionar antes do sort: | filter agent_hostname not in ("<SERVER_NAME>", "JENKINSSRV", "CICD-RUNNER")

config case_sensitive = false
| dataset = xdr_data

// Escopo: eventos de criação de processo em Windows
| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.PROCESS
    and event_sub_type = ENUM.PROCESS_START

// Campos relevantes para análise e alerta
| fields
    _time,
    agent_hostname,
    agent_ip_addresses,
    actor_effective_username,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_command_line,
    action_process_image_name,
    action_process_image_path,
    action_process_image_command_line,
    action_process_image_sha256,
    causality_actor_process_image_name,
    causality_actor_process_image_path,
    causality_actor_process_command_line

// Normalização da linha de comando
| alter action_cmd = lowercase(action_process_image_command_line)

| filter (
        // BLOCO 1: LOLBins nativos fazendo download de hospedagem pública para diretório temporário
        // curl.exe, certutil /urlcache e bitsadmin /transfer são os mais abusados como downloaders
        (
            action_process_image_name in ("curl.exe", "powershell.exe", "pwsh.exe", "certutil.exe", "bitsadmin.exe")
            and action_cmd ~= "(raw\\.githubusercontent\\.com|github\\.com|sourceforge\\.net|cdn\\.discordapp\\.com|workers\\.dev)"
            and action_cmd ~= "\\.(msi|exe|js|ps1|vbs)"
            and action_cmd ~= "(%temp%|\\\\temp\\\\|\\\\appdata\\\\)"
        )
        or
        // BLOCO 2: msiexec em modo silencioso instalando de diretório de usuário
        // Flags /quiet e /qn = instalação sem interação — assinatura característica de dropper
        (
            action_process_image_name = "msiexec.exe"
            and action_cmd ~= "(/i|/quiet|/qn)"
            and action_cmd ~= "(%temp%|\\\\users\\\\[^\\\\]+\\\\appdata\\\\local\\\\temp|\\\\appdata\\\\roaming)"
        )
        or
        // BLOCO 3: PowerShell combinando download + exec via msiexec em linha única
        // One-liner de download→exec é assinatura forte; estes alertas têm prioridade mais alta que BLOCO 1
        (
            action_cmd ~= "(curl|iwr|invoke-webrequest|downloadstring|downloadfile)"
            and action_cmd contains "msiexec"
            and action_cmd ~= "(raw\\.githubusercontent\\.com|github\\.com|sourceforge\\.net)"
        )
)
